/// <summary>
/// Active method of CustTable datasource of CustTable form.Method to determine the behaviour of fields on the form.
/// </summary>
/// <returns>Integer value 1</returns>
public int active()
{
    int ret = next active();

    FormRun formRun = this.formRun();
    CustTable custTable = this.cursor();
    FormDataSource metCustTableDS = formRun.dataSource(formDataSourceStr(CustTable, MetCustTable));
    metCustTableDS.object(fieldNum(METCustTable, eInvoiceVersionId)).allowEdit(custTable.EInvoice);

    return ret;
}
